mapper.select:
select
con.Con_Name as conName, con.Con_Money_Total as conMoneyTotal, con.Con_Code as conCode, con.Con_Type as conType, c1.C_Name as saContractorName, c2.C_Name as saSupervisorName, c3.C_Name as saCostConsultName, c4.C_Name as ssApprovedComName, sa.Sa_Contractor_Amount as saContractorAmount, sa.Sa_Supervisor_Amount as saSupervisorAmount, sa.Sa_Cost_Consult_Amount as saCostConsultAmount, sa.Sa_Approved_Amt as saApprovedAmt, sa.Sa_Historical as saHistorical, mn.* from Inv_Settlement_Second mn left join Inv_Settlement_Apply sa on sa.Sa_Id = mn.Sa_Id left join SYS_Company c1 on sa.Sa_Contractor = c1.C_Id left join SYS_Company c2 on sa.Sa_Supervisor = c2.C_Id left join SYS_Company c3 on sa.Sa_Cost_Consult = c3.C_Id left join SYS_Company c4 on mn.Ss_Approved_Com = c4.C_Id
left join Con_Contract con on con.Con_Id = mn.Con_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Con_Id=#{params.conId}
and con.Con_Type=#{params.conType}
and mn.Ss_History=#{params.ssHistory}
and sa.Sa_Historical=#{params.saHistorical}
and likeCname(#{params.saContractorName},c1.C_Id)=true
and likeCname(#{params.saSupervisorName},c2.C_Id)=true
and likeCname(#{params.saCostConsultName},c3.C_Id)=true
and likeCname(#{params.ssApprovedComName},c4.C_Id)=true
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(c1.C_Name,#{params.saContractorName})
and INSTR(c2.C_Name,#{params.saSupervisorName})
and INSTR(c3.C_Name,#{params.saCostConsultName})
and INSTR(c4.C_Name,#{params.ssApprovedComName})
and INSTR(pro.P_Name,#{params.pName})
and INSTR(con.Con_Name,#{params.conName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC
